using System.Collections.Generic;
using GuateGeeks.AnatomyLab.Core;
namespace GuateGeeks.AnatomyLab.Utilities {
// Original source names remain searchable. Unreviewed translations are identified explicitly.
public static class SpanishAnatomy {
 static readonly Dictionary<string,string> Names=new Dictionary<string,string>{
 {"heart","Corazón"},{"wall of ventricle","Pared ventricular"},{"stomach","Estómago"},{"liver","Hígado"},{"brain","Cerebro"},{"cerebral white matter","Sustancia blanca cerebral"},{"right superior segmental bronchial tree","Árbol bronquial segmentario superior derecho"},{"hepatovenous segment viii","Segmento hepatovenoso VIII"},
 {"right femur","Fémur derecho"},{"left femur","Fémur izquierdo"},{"right kidney","Riñón derecho"},{"left kidney","Riñón izquierdo"},{"right lung","Pulmón derecho"},{"left lung","Pulmón izquierdo"},
 {"spleen","Bazo"},{"pancreas","Páncreas"},{"duodenum","Duodeno"},{"jejunum","Yeyuno"},{"ileum","Íleon"},{"cecum","Ciego"},{"appendix","Apéndice"},{"rectum","Recto"},{"esophagus","Esófago"},{"trachea","Tráquea"},{"larynx","Laringe"},{"tongue","Lengua"},{"mandible","Mandíbula"},{"sternum","Esternón"},{"sacrum","Sacro"},{"coccyx","Cóccix"},{"urinary bladder","Vejiga urinaria"},{"gallbladder","Vesícula biliar"},{"thyroid gland","Glándula tiroides"},{"prostate","Próstata"},{"spinal cord","Médula espinal"},{"aorta","Aorta"},{"ascending aorta","Aorta ascendente"},{"descending aorta","Aorta descendente"},{"abdominal aorta","Aorta abdominal"},{"superior vena cava","Vena cava superior"},{"inferior vena cava","Vena cava inferior"},{"transverse colon","Colon transverso"},{"ascending colon","Colon ascendente"},{"descending colon","Colon descendente"},{"sigmoid colon","Colon sigmoide"},
 {"tendon of left quadriceps femoris","Tendón del cuádriceps femoral izquierdo"},{"tendon of right quadriceps femoris","Tendón del cuádriceps femoral derecho"},
 {"short ciliary nerve","Nervio ciliar corto"},{"optic chiasm","Quiasma óptico"},{"optic chiasma","Quiasma óptico"},{"cerebellum","Cerebelo"},{"hypothalamus","Hipotálamo"},{"medulla oblongata","Bulbo raquídeo"},{"pons","Puente del tronco encefálico"},{"third ventricle","Tercer ventrículo"},{"fourth ventricle","Cuarto ventrículo"},{"cerebral aqueduct","Acueducto cerebral"},{"dura mater","Duramadre"},{"olfactory bulb","Bulbo olfatorio"},{"ciliary processes","Procesos ciliares"}
 };
 static readonly Dictionary<string,string> Paired=new Dictionary<string,string>{{"humerus","Húmero"},{"radius","Radio"},{"ulna","Cúbito"},{"tibia","Tibia"},{"fibula","Peroné"},{"patella","Rótula"},{"scapula","Escápula"},{"clavicle","Clavícula"},{"hip bone","Hueso coxal"},{"testis","Testículo"},{"ureter","Uréter"},{"adrenal gland","Glándula suprarrenal"},{"eyeball","Globo ocular"},
 {"medial rectus","Músculo recto medial"},{"inferior rectus","Músculo recto inferior"},{"superior rectus","Músculo recto superior"},{"lateral rectus","Músculo recto lateral"},{"inferior oblique","Músculo oblicuo inferior"},{"superior oblique","Músculo oblicuo superior"},{"rectus femoris","Músculo recto femoral"},{"levator palpebrae superioris","Músculo elevador del párpado superior"},{"gastrocnemius","Músculo gastrocnemio"},{"adductor longus","Músculo aductor largo"},{"adductor brevis","Músculo aductor corto"},{"adductor magnus","Músculo aductor mayor"},
 {"optic nerve","Nervio óptico"},{"frontal nerve","Nervio frontal"},{"lacrimal nerve","Nervio lagrimal"},{"ophthalmic nerve","Nervio oftálmico"},{"nasociliary nerve","Nervio nasociliar"},{"trochlear nerve","Nervio troclear"},{"anterior ethmoidal nerve","Nervio etmoidal anterior"},{"posterior ethmoidal nerve","Nervio etmoidal posterior"},{"infratrochlear nerve","Nervio infratroclear"},{"supra-orbital nerve","Nervio supraorbitario"},{"supratrochlear nerve","Nervio supratroclear"},{"long ciliary nerve","Nervio ciliar largo"},
 {"retina","Retina"},{"fovea centralis","Fóvea central"},{"macula lutea","Mácula lútea"},{"optic disc","Disco óptico"},{"pupil","Pupila"},{"sclera","Esclerótica"},{"choroid","Coroides"},{"lens","Cristalino"},{"iris","Iris"},{"cornea","Córnea"},{"ciliary body","Cuerpo ciliar"},{"ciliary muscle","Músculo ciliar"},{"ora serrata","Ora serrata"},{"bulbar conjunctiva","Conjuntiva bulbar"}};
 static readonly string[] Ordinals={"first","second","third","fourth","fifth","sixth","seventh","eighth","ninth","tenth","eleventh","twelfth"};
 public static void Apply(AnatomyCatalog catalog){foreach(var d in catalog.structures){if(d.localized)continue;string original=d.canonicalName.ToLowerInvariant();bool translated=Names.TryGetValue(original,out var name);
 if(!translated)foreach(var pair in Paired)foreach(var side in new[]{"right","left"})if(original==side+" "+pair.Key){bool feminine=pair.Value.EndsWith("a")||pair.Value.StartsWith("Glándula");name=pair.Value+" "+(side=="right"?(feminine?"derecha":"derecho"):(feminine?"izquierda":"izquierdo"));translated=true;}
 if(!translated)for(int i=0;i<Ordinals.Length;i++)foreach(var side in new[]{"right","left"})if(original==side+" "+Ordinals[i]+" rib"){name="Costilla "+(i+1)+" "+(side=="right"?"derecha":"izquierda");translated=true;}
 string system="anatómico";foreach(var s in catalog.systems)if(s.id==d.systemId)system=s.displayName.ToLowerInvariant();
 d.displayName=translated?name:"Estructura · "+system+" · "+d.id;
 d.description=translated?"Estructura anatómica de referencia. Explora su posición y relación con las piezas cercanas.":"Estructura del grupo "+system+". Identificador: "+d.id+". Nombre específico pendiente de traducción anatómica revisada.";
 }}
}
}
